package com.lovemaptually.entity;
import jakarta.persistence.*;import lombok.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import static com.lovemaptually.entity.Enums.*;
@Entity @Table(name="review_tags",uniqueConstraints=@UniqueConstraint(name="uq_review_tags_pair",columnNames={"review_id","tag_id"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class ReviewTag {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long reviewTagId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="review_id") private Review review;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tag_id") private Tag tag;@Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(columnDefinition="attr_level") private AttrLevel factValue;@Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(columnDefinition="attr_level") private AttrLevel wantValue;@Column(columnDefinition="text") private String evidenceText;}
